script:
const colors = { '青绿': '#24776d', '靛蓝': '#525da6', '朱红': '#a34238' };
const accent = colors[api.preferences.accent];
if (accent) api.ui.addStyle(':root { --eidos-palette-accent: ' + accent + '; }');
api.actions.beforeSubmit(input => input.trim() === '/环顾' ? '仔细观察当前环境，留意可见的人物、物品与出入口。' : input);
if (api.preferences['compact-layout'] === true) api.ui.addStyle('.eidos-settings-row { padding-top: .6rem; padding-bottom: .6rem; } .eidos-record-scroll .eidos-story-paper { padding-top: 1.2rem; padding-bottom: 1.2rem; } .eidos-record-scroll [data-reading-text] { line-height: 1.75; } .eidos-archive-header h1 { letter-spacing: -.03em; }');
